export type Topic = (typeof TOPICS)[number]["id"];

export type Quote = { id: string; text: string; by: string; topics: Topic[] };
export type Verse = { id: string; ref: string; text: string; topics: Topic[] };
export type Story = { id: string; title: string; ref: string; body: string[]; lesson: string; topics: Topic[]; faith: boolean };
export type Advice = { id: string; title: string; body: string; topics: Topic[]; tone: "gentle" | "tough" | "wise" | "practical" };
export type Line = { id: string; text: string; topics: Topic[] };
export type Challenge = { id: string; title: string; how: string; mins: number; topics: Topic[] };
export type Lesson = { id: string; title: string; idea: string; try: string; topics: Topic[] };

